"""
Temporal Label Model (TLM) — temporal-aware label aggregation.

Two methods for aggregating LF votes by exploiting temporal dynamics:
  TWV: Gaussian-convolution temporal shift based on measured LF lead/lag profiles
  HMM-TLM: Hidden Markov Model with per-LF emission parameters and EM learning

Input:  windows_labeled.jsonl with per-LF votes grouped by trajectory
Output: per-window labels that respect temporal structure of LF firing patterns

Label convention: 0=stagnation, 1=progress, -1=abstain
"""

import json
import numpy as np
from collections import defaultdict

LF_NAMES = ["command_repetition", "file_diff_delta", "outcome_backpropagation"]

# From lf-temporal-dynamics experiment (KW H=274.3, p=2.74e-60)
DEFAULT_LAG_PROFILES = {
    "command_repetition": -1.866,
    "file_diff_delta": -1.201,
    "outcome_backpropagation": 6.697,
}


def load_trajectories(data_path):
    trajectories = defaultdict(list)
    with open(data_path) as f:
        for line in f:
            rec = json.loads(line)
            trajectories[rec["trajectory_id"]].append(rec)
    for tid in trajectories:
        trajectories[tid].sort(key=lambda w: w["window_idx"])
    return dict(trajectories)


class TemporalWeightedVoter:
    """Gaussian-convolution temporal shift on LF votes.

    For LF with lag mu, vote at time t' contributes to target time t with
    weight G(t - t' + mu, sigma). Positive aggregate = stagnation.
    """

    def __init__(self, lag_profiles=None, sigma=2.0):
        self.lag_profiles = lag_profiles or DEFAULT_LAG_PROFILES
        self.sigma = sigma

    def predict_trajectory(self, windows):
        T = len(windows)
        if T == 0:
            return []
        indices = np.array([w["window_idx"] for w in windows], dtype=np.float64)
        scores = np.zeros(T)

        for lf in LF_NAMES:
            lag = self.lag_profiles[lf]
            votes = np.array([
                1.0 if w["labels"][lf] == 0 else
                (-1.0 if w["labels"][lf] == 1 else 0.0)
                for w in windows
            ])
            dt = indices[:, None] - indices[None, :] + lag
            weights = np.exp(-dt ** 2 / (2.0 * self.sigma ** 2))
            scores += weights @ votes

        return [
            {
                "window_idx": int(windows[t]["window_idx"]),
                "tlm_label": 0 if scores[t] > 0 else 1,
                "tlm_score": float(scores[t]),
                "mv_label": windows[t]["majority_label"],
                "confidence": windows[t]["confidence"],
            }
            for t in range(T)
        ]

    def predict_all(self, trajectories, verbose=True):
        results = {}
        for i, (tid, windows) in enumerate(trajectories.items()):
            results[tid] = self.predict_trajectory(windows)
            if verbose and (i + 1) % 1000 == 0:
                print(f"  TWV: {i + 1}/{len(trajectories)}")
        return results


