def lf_error_repetition(steps, threshold=3):
    """Repeated errors in window → stagnation."""
    error_sigs = []
    for step in steps:
        if step.role != "user" or step.index == 0:
            continue
        text = step.text
        if "Traceback" not in text and "Error" not in text:
            continue
        lines = text.strip().splitlines()
        for line in reversed(lines):
            line = line.strip()
            if line and ("Error" in line or "Exception" in line):
                error_sigs.append(line[:200])
                break
        else:
            error_sigs.append("_generic_error_")
    if len(error_sigs) < 2:
        return ABSTAIN
    counter = Counter(error_sigs)
    if counter.most_common(1)[0][1] >= threshold:
        return STAGNATION
    return ABSTAIN


