def _lse(x):
    m = np.max(x)
    return -np.inf if m == -np.inf else m + np.log(np.sum(np.exp(x - m)))


class HMM6:
    def __init__(self):
        self.pi = None
        self.A = None
        self.emission = {}

    def _init(self, trajectories):
        pi = np.ones(2) * 1e-6
        A = np.ones((2, 2)) * 1e-6
        em = {lf: np.ones((2, 3)) * 1e-6 for lf in LF6}
