    def _forward(self, le):
        T = le.shape[0]
        lA = np.log(self.A + 1e-300)
        la = np.full((T, 2), -np.inf)
        la[0] = np.log(self.pi + 1e-300) + le[0]
        for t in range(1, T):
            for s in range(2):
                la[t, s] = _lse(la[t-1] + lA[:, s]) + le[t, s]
        return la

    def _backward(self, le):
        T = le.shape[0]
        lA = np.log(self.A + 1e-300)
        lb = np.zeros((T, 2))
        for t in range(T-2, -1, -1):
            for s in range(2):
                lb[t, s] = _lse(lA[s, :] + le[t+1] + lb[t+1])
        return lb

    def fit(self, trajectories, n_iter=20, verbose=True):
