            self.emission = {lf: emc[lf] / emc[lf].sum(axis=1, keepdims=True) for lf in LF6}
            if verbose:
                print(f"  EM {it+1}: LL={total_ll:.1f}, A=[{self.A[0,0]:.3f},{self.A[1,1]:.3f}]")
            if abs(total_ll - prev_ll) < 1.0:
                if verbose:
                    print(f"  Converged at {it+1}")
