            results[tid] = [{
                "window_idx": int(ws[t]["window_idx"]),
                "tlm_label": int(path[t]),
                "mv_label": ws[t].get("mv6_label", -1),
                "confidence": ws[t].get("mv6_conf", 0),
            } for t in range(T)]
        return results


# ═══════════════════════════════════════════════════════════════════
# Lag-aware HMM with 6 LFs
# ═══════════════════════════════════════════════════════════════════

class LagHMM6:
    def __init__(self, a_prior=5000, anchor_conf=2):
        self.pi = np.array([0.285, 0.715])
        self.A = None
        self.A_prior = None
        self.emission = {}
        self.a_prior = a_prior
        self.anchor_conf = anchor_conf

    def _shifted_obs(self, ws, t, lf):
        t2 = t + LAG_OFFSETS_6[lf]
        if 0 <= t2 < len(ws):
            return _vi(ws[t2]["labels"].get(lf, -1))
        return None

    def _init(self, trajectories):
        A = np.ones((2, 2)) * 1e-6
        em = {lf: np.ones((2, 3)) * 1.0 for lf in LF6}
        for ws in trajectories.values():
            for t in range(len(ws)):
                s = ws[t].get("mv6_label", -1)
                if s not in (0, 1):
                    continue
                if t > 0:
                    ps = ws[t-1].get("mv6_label", -1)
                    if ps in (0, 1):
                        A[ps, s] += 1
                for lf in LF6:
                    v = self._shifted_obs(ws, t, lf)
                    if v is not None:
                        em[lf][s, v] += 1
        self.A = A / A.sum(axis=1, keepdims=True)
        self.A_prior = self.A.copy() * self.a_prior
        self.emission = {lf: em[lf] / em[lf].sum(axis=1, keepdims=True) for lf in LF6}

    def _log_em(self, ws):
        T = len(ws)
        le = np.zeros((T, 2))
        for lf in LF6:
            lem = np.log(self.emission[lf] + 1e-300)
            for t in range(T):
                v = self._shifted_obs(ws, t, lf)
                if v is not None:
                    le[t] += lem[:, v]
        return le

    def _forward(self, le):
        T = le.shape[0]
        lA = np.log(self.A + 1e-300)
        la = np.full((T, 2), -np.inf)
        la[0] = np.log(self.pi + 1e-300) + le[0]
        for t in range(1, T):
            for s in range(2):
                la[t, s] = _lse(la[t-1] + lA[:, s]) + le[t, s]
        return la

    def _backward(self, le):
        T = le.shape[0]
        lA = np.log(self.A + 1e-300)
        lb = np.zeros((T, 2))
        for t in range(T-2, -1, -1):
            for s in range(2):
                lb[t, s] = _lse(lA[s, :] + le[t+1] + lb[t+1])
        return lb

    def fit(self, trajectories, n_iter=20, verbose=True):
        self._init(trajectories)
        if verbose:
            print(f"  LagHMM6 init: A=[{self.A[0,0]:.3f},{self.A[1,1]:.3f}]")
        prev_ll = -np.inf
        for it in range(n_iter):
            all_g, all_xi = {}, {}
            total_ll = 0
            for tid, ws in trajectories.items():
                T = len(ws)
                if T == 0:
                    continue
                le = self._log_em(ws)
                la = self._forward(le)
                lb = self._backward(le)
                lg = la + lb
                ll = _lse(la[T-1])
                total_ll += ll
                g = np.exp(lg - np.array([_lse(lg[t]) for t in range(T)])[:, None])
                g = np.clip(g, 1e-300, None)
                g /= g.sum(axis=1, keepdims=True)
                for t in range(T):
                    c = ws[t].get("mv6_conf", 0)
                    if c >= self.anchor_conf:
                        s = ws[t].get("mv6_label", -1)
                        if s == 0:
                            g[t] = [0.999, 0.001]
                        elif s == 1:
                            g[t] = [0.001, 0.999]
                all_g[tid] = g
                if T > 1:
                    lA = np.log(self.A + 1e-300)
                    xi = np.zeros((T-1, 2, 2))
                    for t in range(T-1):
                        raw = la[t, :, None] + lA + (le[t+1] + lb[t+1])[None, :]
                        xi[t] = np.exp(raw - _lse(raw))
                    all_xi[tid] = xi
            # M-step
            pi = np.ones(2) * 1e-6
            An = self.A_prior.copy()
            emc = {lf: np.ones((2, 3)) * 1e-6 for lf in LF6}
            for tid in trajectories:
                if tid not in all_g:
                    continue
                g = all_g[tid]
                pi += g[0]
                if tid in all_xi:
                    An += all_xi[tid].sum(axis=0)
                ws = trajectories[tid]
                for t in range(len(ws)):
                    for lf in LF6:
                        v = self._shifted_obs(ws, t, lf)
                        if v is not None:
                            emc[lf][:, v] += g[t]
            self.pi = pi / pi.sum()
            self.A = An / An.sum(axis=1, keepdims=True)
            self.emission = {lf: emc[lf] / emc[lf].sum(axis=1, keepdims=True) for lf in LF6}
            if verbose:
                print(f"  EM {it+1}: LL={total_ll:.1f}, A=[{self.A[0,0]:.3f},{self.A[1,1]:.3f}]")
            if abs(total_ll - prev_ll) < 1.0:
                if verbose:
                    print(f"  Converged at {it+1}")
                break
            prev_ll = total_ll
        return self

    def predict_all(self, trajectories, stag_thresh=0.3):
        results = {}
        for tid, ws in trajectories.items():
            T = len(ws)
            if T == 0:
                results[tid] = []
                continue
            le = self._log_em(ws)
            la = self._forward(le)
            lb = self._backward(le)
            lg = la + lb
            lg_n = np.array([_lse(lg[t]) for t in range(T)])
            lg -= lg_n[:, None]
            post = np.exp(np.clip(lg, -500, 0))
            post /= post.sum(axis=1, keepdims=True)
            results[tid] = [{
                "window_idx": int(ws[t]["window_idx"]),
                "tlm_label": 0 if post[t, 0] > stag_thresh else 1,
                "mv_label": ws[t].get("mv6_label", -1),
                "confidence": ws[t].get("mv6_conf", 0),
            } for t in range(T)]
        return results


# ═══════════════════════════════════════════════════════════════════
# Evaluation
# ═══════════════════════════════════════════════════════════════════

def eval_gold(flat_labels, gold):
    tp = fp = tn = fn = 0
    for gid, truth in gold.items():
        pred = flat_labels.get(gid)
        if pred is None or pred == -1:
            continue
        if pred == 0 and truth == 0: tp += 1
        elif pred == 0 and truth == 1: fp += 1
        elif pred == 1 and truth == 1: tn += 1
        elif pred == 1 and truth == 0: fn += 1
    n = tp + fp + tn + fn
    ps = tp/(tp+fp) if tp+fp else 0
    rs = tp/(tp+fn) if tp+fn else 0
    fs = 2*ps*rs/(ps+rs) if ps+rs else 0
    pp = tn/(tn+fn) if tn+fn else 0
    rp = tn/(tn+fp) if tn+fp else 0
    fp2 = 2*pp*rp/(pp+rp) if pp+rp else 0
    return {
        "n": n, "acc": round((tp+tn)/n, 4) if n else 0,
        "macro_f1": round((fs+fp2)/2, 4),
        "f1_stag": round(fs, 4), "f1_prog": round(fp2, 4),
    }


def eval_conf2(results, min_conf=2):
    tp = fp = tn = fn = 0
    for tid, recs in results.items():
        for r in recs:
            if r["confidence"] < min_conf:
                continue
            if r["mv_label"] not in (0, 1):
                continue
            pred = r["tlm_label"]
            mv = r["mv_label"]
            if pred == 0 and mv == 0: tp += 1
            elif pred == 0 and mv == 1: fp += 1
            elif pred == 1 and mv == 1: tn += 1
            elif pred == 1 and mv == 0: fn += 1
    n = tp + fp + tn + fn
    ps = tp/(tp+fp) if tp+fp else 0
    rs = tp/(tp+fn) if tp+fn else 0
    fs = 2*ps*rs/(ps+rs) if ps+rs else 0
    pp = tn/(tn+fn) if tn+fn else 0
    rp = tn/(tn+fp) if tn+fp else 0
    fp2 = 2*pp*rp/(pp+rp) if pp+rp else 0
    agr = (tp+tn)/n if n else 0
    return {
        "n": n, "agreement": round(agr, 4),
        "macro_f1": round((fs+fp2)/2, 4),
        "f1_stag": round(fs, 4), "f1_prog": round(fp2, 4),
    }


def eval_gold_from_results(results, gold):
    flat = {}
    for tid, recs in results.items():
        for r in recs:
            flat[f"{tid}__w{r['window_idx']}"] = r["tlm_label"]
    return eval_gold(flat, gold)


def flatten(results):
    flat = {}
    for tid, recs in results.items():
        for r in recs:
            flat[f"{tid}__w{r['window_idx']}"] = r["tlm_label"]
    return flat


# ═══════════════════════════════════════════════════════════════════
# Main
# ═══════════════════════════════════════════════════════════════════

def main():
    t0 = time.time()

    print("=" * 65)
    print("  6-LF TLM EXPERIMENT")
    print("=" * 65)

    # ── Phase 1: Load / compute 6-LF labels ──
    if CACHE_PATH.exists():
        print(f"\nLoading cached 6-LF windows from {CACHE_PATH}...")
        windows = []
        with open(CACHE_PATH) as f:
            for line in f:
                if line.strip():
                    windows.append(json.loads(line))
        print(f"  {len(windows)} windows loaded")
    else:
        print("\nLoading 3-LF windows...")
        windows = load_windows()
        print(f"  {len(windows)} windows")
        windows = compute_6lf_labels(windows)
        print(f"Caching to {CACHE_PATH}...")
        with open(CACHE_PATH, "w") as f:
            for w in windows:
                f.write(json.dumps(w) + "\n")
        print("  Cached.")

    # Recompute 6-LF MV
    for w in windows:
        label, conf = majority_vote_6(w["labels"])
        w["mv6_label"] = label
        w["mv6_conf"] = conf

    # MV stats
    n_labeled = sum(1 for w in windows if w["mv6_label"] != -1)
    conf_dist = Counter(w["mv6_conf"] for w in windows if w["mv6_label"] != -1)
    print(f"\n6-LF MV: {n_labeled}/{len(windows)} labeled ({100*n_labeled/len(windows):.1f}%)")
    print(f"  Conf distribution: {dict(sorted(conf_dist.items()))}")

    # Build trajectory dict (ALL windows for temporal structure)
    traj = defaultdict(list)
    for w in windows:
        traj[w["trajectory_id"]].append(w)
    for tid in traj:
        traj[tid].sort(key=lambda x: x["window_idx"])
    traj = dict(traj)
    print(f"  Trajectories: {len(traj)}")

    # Load gold
    gold = load_gold()
    print(f"  Gold set: {len(gold)}")

    # 6-LF MV gold eval (validation: should match ~0.7192)
    mv6_flat = {wid(w): w["mv6_label"] for w in windows if w["mv6_label"] != -1}
    mv6_gold = eval_gold(mv6_flat, gold)
    print(f"\n  6-LF MV gold: {mv6_gold}")
    if abs(mv6_gold["macro_f1"] - 0.7192) > 0.005:
        print(f"  WARNING: expected ~0.7192, got {mv6_gold['macro_f1']:.4f} - label mismatch?")

    all_results = {"6lf_mv": {"gold": mv6_gold}}

    # ── Phase 2: TLM experiments ──
    print("\n" + "=" * 65)
    print("  TWV SIGMA SWEEP")
    print("=" * 65)
    for sigma in [1.0, 2.0, 3.0, 5.0]:
        print(f"\n--- TWV sigma={sigma} ---")
        twv = TWV6(sigma=sigma)
        res = twv.predict_all(traj)
        geval = eval_gold_from_results(res, gold)
        c2eval = eval_conf2(res, min_conf=2)
        c3eval = eval_conf2(res, min_conf=3)
        print(f"  Gold:   {geval}")
        print(f"  Conf>=2: {c2eval}")
        print(f"  Conf>=3: {c3eval}")
        all_results[f"twv_s{sigma}"] = {"gold": geval, "conf2": c2eval, "conf3": c3eval}

    print("\n" + "=" * 65)
    print("  HMM (Viterbi)")
    print("=" * 65)
    hmm = HMM6()
    hmm.fit(traj)
    res = hmm.predict_all(traj)
    geval = eval_gold_from_results(res, gold)
    c2eval = eval_conf2(res, min_conf=2)
    c3eval = eval_conf2(res, min_conf=3)
    print(f"  Gold:   {geval}")
    print(f"  Conf>=2: {c2eval}")
    print(f"  Conf>=3: {c3eval}")
    all_results["hmm"] = {"gold": geval, "conf2": c2eval, "conf3": c3eval}

    print("\n" + "=" * 65)
    print("  LAG-AWARE HMM (conf-anchored)")
    print("=" * 65)
    lhmm = LagHMM6()
    lhmm.fit(traj)
    res = lhmm.predict_all(traj)
    geval = eval_gold_from_results(res, gold)
    c2eval = eval_conf2(res, min_conf=2)
    c3eval = eval_conf2(res, min_conf=3)
    print(f"  Gold:   {geval}")
    print(f"  Conf>=2: {c2eval}")
    print(f"  Conf>=3: {c3eval}")
    all_results["lag_hmm"] = {"gold": geval, "conf2": c2eval, "conf3": c3eval}

    # ── Phase 3: Comparison ──
    print("\n" + "=" * 65)
    print("  COMPARISON TABLE")
    print("=" * 65)

    hdr = f"{'Method':<22} {'Gold F1':>8} {'GoldAcc':>8} {'C2 F1':>8} {'C2 Agr':>8} {'C3 F1':>8} {'C3 Agr':>8}"
    print(f"\n{hdr}")
    print("-" * len(hdr))

    # 3-LF reference (probe-based, not directly comparable)
    print(f"{'3-LF MV':<22} {'0.6818':>8} {'0.7295':>8} {'0.8946':>8} {'---':>8} {'---':>8} {'---':>8}  [probe]")
    print(f"{'3-LF TWV s=2':<22} {'---':>8} {'---':>8} {'0.9003':>8} {'---':>8} {'---':>8} {'---':>8}  [probe]")
    print(f"{'3-LF HMM':<22} {'---':>8} {'---':>8} {'0.7502':>8} {'---':>8} {'---':>8} {'---':>8}  [probe]")
    print(f"{'3-LF lag-HMM':<22} {'---':>8} {'---':>8} {'0.8936':>8} {'---':>8} {'---':>8} {'---':>8}  [probe]")
    print("-" * len(hdr))

    r = all_results["6lf_mv"]
    print(f"{'6-LF MV':<22} {r['gold']['macro_f1']:>8.4f} {r['gold']['acc']:>8.4f} {'(base)':>8} {'1.000':>8} {'(base)':>8} {'1.000':>8}")

    for sigma in [1.0, 2.0, 3.0, 5.0]:
        k = f"twv_s{sigma}"
        r = all_results[k]
        name = f"6-LF TWV s={sigma}"
        print(f"{name:<22} {r['gold']['macro_f1']:>8.4f} {r['gold']['acc']:>8.4f} "
              f"{r['conf2']['macro_f1']:>8.4f} {r['conf2']['agreement']:>8.4f} "
              f"{r['conf3']['macro_f1']:>8.4f} {r['conf3']['agreement']:>8.4f}")

    r = all_results["hmm"]
    print(f"{'6-LF HMM':<22} {r['gold']['macro_f1']:>8.4f} {r['gold']['acc']:>8.4f} "
          f"{r['conf2']['macro_f1']:>8.4f} {r['conf2']['agreement']:>8.4f} "
          f"{r['conf3']['macro_f1']:>8.4f} {r['conf3']['agreement']:>8.4f}")

    r = all_results["lag_hmm"]
    print(f"{'6-LF lag-HMM':<22} {r['gold']['macro_f1']:>8.4f} {r['gold']['acc']:>8.4f} "
          f"{r['conf2']['macro_f1']:>8.4f} {r['conf2']['agreement']:>8.4f} "
          f"{r['conf3']['macro_f1']:>8.4f} {r['conf3']['agreement']:>8.4f}")

    # Deltas vs 6-LF MV
    mv6_f1 = all_results["6lf_mv"]["gold"]["macro_f1"]
    print(f"\nDelta vs 6-LF MV (gold F1):")
    for k in [f"twv_s{s}" for s in [1,2,3,5]] + ["hmm", "lag_hmm"]:
        d = all_results[k]["gold"]["macro_f1"] - mv6_f1
        print(f"  {k:>15}: {d:+.4f}")

    # Best TLM
    best_k = max(
        [f"twv_s{s}" for s in [1,2,3,5]] + ["hmm", "lag_hmm"],
        key=lambda k: all_results[k]["gold"]["macro_f1"]
    )
    best_f1 = all_results[best_k]["gold"]["macro_f1"]

    print(f"\nBest TLM: {best_k} (gold F1={best_f1:.4f})")
    delta = best_f1 - mv6_f1
    print(f"Delta vs 6-LF MV: {delta:+.4f}")

    # Conclusion
    print(f"\n{'='*65}")
    if delta > 0.02:
        verdict = "TLM BEATS 6-LF MV → C3 claim needs revision"
    elif delta > 0.005:
        verdict = "TLM marginally better → C3 claim weakened but holds"
    elif delta > -0.005:
        verdict = "TLM ≈ MV → C3 claim holds: no meaningful improvement"
    else:
        verdict = "TLM WORSE than MV → C3 claim STRENGTHENED"
    print(f"  VERDICT: {verdict}")
    print(f"{'='*65}")

    # Save
    all_results["lf_names"] = LF6
    all_results["lag_profiles"] = LAG_PROFILES_6
    all_results["lag_offsets"] = LAG_OFFSETS_6
    all_results["3lf_reference"] = {
        "mv_conf2_f1_probe": 0.8946, "twv_s2_conf2_f1_probe": 0.9003,
        "hmm_conf2_f1_probe": 0.7502, "lag_hmm_conf2_f1_probe": 0.8936,
        "mv_gold_f1": 0.6818,
    }
    all_results["notes"] = {
        "3lf_conf2_f1": "probe cross-eval (train on TLM labels, eval on MV conf>=2 test set)",
        "6lf_gold_f1": "direct label eval against gold consensus (N=601)",
        "6lf_conf2_f1": "direct label agreement with 6-LF MV on conf>=2 subset",
        "new_lf_lag_profiles": "estimated: low_file_div=0, action_entropy=0, output_stag=-1 (no empirical measurement)",
    }

    out = OUT_DIR / "6lf_tlm_results.json"
    with open(out, "w") as f:
        json.dump(all_results, f, indent=2, default=str)
    print(f"\nSaved: {out}")
    print(f"Total: {time.time()-t0:.1f}s")


if __name__ == "__main__":
    main()
